(()=>{const page=document.getElementById('dialogue-page'),text=document.getElementById('terminal-text'),announcement=document.getElementById('terminal-announcement'),back=document.getElementById('dialogue-back'),next=document.getElementById('dialogue-next'),skip=document.getElementById('dialogue-skip'),counter=document.getElementById('dialogue-count'),camera=document.getElementById('camera-page'),quote=document.querySelector('.central-quote');
const sentences=[
'For millennia, women have been constrained by oppressive customs, restrictive laws and disproportionate social expectations.',
'Central to this subordination is the enduring construction of women as the “weaker sex”, fragile and in need of protection, a notion that paradoxically legitimised male control.',
'Although the expansion of human rights discourse has since given women greater scope for advocacy, a structural imbalance persists: power in parliaments, corporate boardrooms and most decision-making spaces remains predominantly male.',
'This imbalance illustrates why the central question of gender equality is, at its core, a question of power: who holds it, who is excluded from it, and who has the authority to redistribute it.',
'Substantive change therefore requires not only the efforts of those seeking access, but also the cooperation of those who already hold power.',
'Accordingly, contemporary feminism depends on the engagement of progressive men willing to cede decision-making space and use their influence to amplify women’s voices.',
'Gender equality, the core objective of SDG 5, should thus be understood not as a women’s issue but as a collective societal responsibility.',
'Hence the call to action: “Pass the mic. Nominate a woman. Change who decides.”'];
let index=0,raf=0,inView=false,started=false;const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function typeSentence(){cancelAnimationFrame(raf);const words=sentences[index].split(' '),start=performance.now();text.textContent='';text.classList.toggle('emphasis',index===3);back.disabled=false;counter.textContent=` ${index+1}/${sentences.length}`;announcement.textContent=sentences[index];let count=-1;function tick(now){const n=reduced.matches?words.length:Math.min(words.length,Math.floor((now-start)/2000*words.length));if(n!==count){text.textContent=words.slice(0,n).join(' ');count=n}if(n<words.length)raf=requestAnimationFrame(tick)}raf=requestAnimationFrame(tick)}
function advance(delta){if(index+delta<0){document.querySelector('.quote-page').scrollIntoView({behavior:reduced.matches?'instant':'smooth'});return}if(index+delta>=sentences.length){camera.scrollIntoView({behavior:reduced.matches?'instant':'smooth'});return}index+=delta;typeSentence()}
back.addEventListener('click',()=>advance(-1));next.addEventListener('click',()=>advance(1));skip.addEventListener('click',()=>camera.scrollIntoView({behavior:reduced.matches?'instant':'smooth'}));
addEventListener('keydown',e=>{if(!inView||e.repeat||e.target.isContentEditable||e.target.closest('input,textarea,select,#customize-panel'))return;if(e.key==='Enter'||e.key==='Backspace'){e.preventDefault();advance(e.key==='Enter'?1:-1)}});
new IntersectionObserver(entries=>{inView=entries[0].isIntersecting&&entries[0].intersectionRatio>.35;if(inView&&!started){started=true;typeSentence()}document.body.classList.toggle('terminal-active',inView);document.dispatchEvent(new Event('site-style-change'))},{threshold:[0,.35,.6]}).observe(page);
// The first scroll starts one continuous quote sequence; further scroll events do not restart it.
const glyphs=[...quote.querySelectorAll('.quote-line')],original=glyphs.map(e=>e.innerHTML);let introStarted=false,introFinished=false,introRaf=0;
function intro(){if(introStarted||document.getElementById('home-panel').hidden)return;introStarted=true;quote.classList.add('quote-typing');glyphs.forEach(e=>e.style.visibility='hidden');const overlay=document.createElement('span');overlay.className='quote-type-preview';quote.append(overlay);const line='<title>“The central question of gender equality is a question of power.”</title>',start=performance.now();function tick(now){const n=Math.min(line.length,Math.floor((now-start)/2200*line.length));overlay.textContent=line.slice(0,n);if(n<line.length){introRaf=requestAnimationFrame(tick);return}overlay.remove();glyphs.forEach((e,i)=>{e.innerHTML=original[i];e.style.visibility=''});quote.classList.add('quote-reveal');setTimeout(()=>quote.classList.add('quote-gender'),240);setTimeout(()=>quote.classList.add('quote-power'),800);setTimeout(()=>{quote.classList.remove('quote-typing');introFinished=true},1500)}if(reduced.matches){glyphs.forEach(e=>e.style.visibility='');overlay.remove();quote.classList.remove('quote-typing');introFinished=true;return}introRaf=requestAnimationFrame(tick)}
function scrollIntro(e){const landing=document.querySelector('.quote-page').getBoundingClientRect();if(!introFinished&&!document.getElementById('home-panel').hidden&&landing.top>=-80){e.preventDefault();intro()}}addEventListener('wheel',scrollIntro,{passive:false});addEventListener('touchmove',scrollIntro,{passive:false});addEventListener('keydown',e=>{if(['PageDown','ArrowDown',' '].includes(e.key))intro()});addEventListener('pagehide',()=>{cancelAnimationFrame(raf);cancelAnimationFrame(introRaf)});
})();
